COMMENT ON TABLE app_users IS 'Default users for local development and conformance testing. Lives in the rulebook so it travels with the project; production deployments should overlay these with a real identity provider.';
COMMENT ON COLUMN app_users.email IS 'Login identifier (no password in dev mode; presence in this list = authorized)';
COMMENT ON COLUMN app_users.role_id IS 'FK to UserRoles.RoleId (Viewer or Developer)';
COMMENT ON COLUMN app_users.is_default IS 'True for the user the portal auto-selects on first boot';

-- ----------------------------------------------------------------------------
-- UserRoles: Admin portal access tiers. Each role is a PERSONA with its own landing screen, tagline, and bespoke screen overrides (see RoleScreenHints). NOT a CRUD form — every role gets a UX shaped for what that person actually cares about. Also drives RLS policies that Postgres applies to portal writes.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS user_roles (
  role_id                             TEXT                 PRIMARY KEY
);
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS name TEXT;
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS persona TEXT;                                       -- One-line description of WHO this role is — the kind of person who logs in as this role
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS tagline TEXT;                                       -- Short motto shown on the role's landing screen — sets the mood
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS primary_concerns TEXT;                              -- What this role spends time on. Comma-separated, used by the home screen to bubble these things up.
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS landing_screen_id TEXT;                             -- Soft reference to AppScreens.ScreenId (the screen this role lands on after login). Deliberately NOT a relationship: AppScreens.MinRoleId already points AppScreens -> UserRoles, and a FK here would create a table-level cycle. The portal resolves it at read time.
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS color_theme TEXT;                                   -- CSS accent colour for the role's pill / chrome — quick visual identity
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS access_level TEXT;                                  -- read | write | full-admin
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS can_edit_rulebook BOOLEAN;
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS can_run_builds BOOLEAN;
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS can_access_tech_tools BOOLEAN;                      -- Tech Tools nest = raw Postgres explorer, ssotme-proxy logs, conformance internals
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS can_switch_projects BOOLEAN;
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS can_manage_users BOOLEAN;
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS description TEXT;
COMMENT ON TABLE user_roles IS 'Admin portal access tiers. Each role is a PERSONA with its own landing screen, tagline, and bespoke screen overrides (see RoleScreenHints). NOT a CRUD form — every role gets a UX shaped for what that person actually cares about. Also drives RLS policies that Postgres applies to portal writes.';
COMMENT ON COLUMN user_roles.persona IS 'One-line description of WHO this role is — the kind of person who logs in as this role';
COMMENT ON COLUMN user_roles.tagline IS 'Short motto shown on the role''s landing screen — sets the mood';
COMMENT ON COLUMN user_roles.primary_concerns IS 'What this role spends time on. Comma-separated, used by the home screen to bubble these things up.';
COMMENT ON COLUMN user_roles.landing_screen_id IS 'Soft reference to AppScreens.ScreenId (the screen this role lands on after login). Deliberately NOT a relationship: AppScreens.MinRoleId already points AppScreens -> UserRoles, and a FK here would create a table-level cycle. The portal resolves it at read time.';
COMMENT ON COLUMN user_roles.color_theme IS 'CSS accent colour for the role''s pill / chrome — quick visual identity';
COMMENT ON COLUMN user_roles.access_level IS 'read | write | full-admin';
COMMENT ON COLUMN user_roles.can_access_tech_tools IS 'Tech Tools nest = raw Postgres explorer, ssotme-proxy logs, conformance internals';

-- ----------------------------------------------------------------------------
-- AppPermissions: RLS-style policy table: declarative per-role allow/deny on portal API endpoints and on Postgres tables. Generated into Postgres on portal bootstrap as RLS policies.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS app_permissions (
  permission_id                       TEXT                 PRIMARY KEY
);
ALTER TABLE app_permissions ADD COLUMN IF NOT EXISTS role_id TEXT;                                  -- FK to UserRoles.RoleId
ALTER TABLE app_permissions ADD COLUMN IF NOT EXISTS resource TEXT;                                 -- Logical resource: rulebook.entity, rulebook.field, rulebook.formula, build, test, users, tech-tools.postgres, tech-tools.proxy
ALTER TABLE app_permissions ADD COLUMN IF NOT EXISTS "action" TEXT;                                 -- read | create | update | delete | execute
ALTER TABLE app_permissions ADD COLUMN IF NOT EXISTS allow BOOLEAN;
ALTER TABLE app_permissions ADD COLUMN IF NOT EXISTS rls_predicate TEXT;                            -- Postgres RLS USING clause (when applicable); null for endpoint-only checks
COMMENT ON TABLE app_permissions IS 'RLS-style policy table: declarative per-role allow/deny on portal API endpoints and on Postgres tables. Generated into Postgres on portal bootstrap as RLS policies.';
COMMENT ON COLUMN app_permissions.role_id IS 'FK to UserRoles.RoleId';
COMMENT ON COLUMN app_permissions.resource IS 'Logical resource: rulebook.entity, rulebook.field, rulebook.formula, build, test, users, tech-tools.postgres, tech-tools.proxy';
COMMENT ON COLUMN app_permissions."action" IS 'read | create | update | delete | execute';
COMMENT ON COLUMN app_permissions.rls_predicate IS 'Postgres RLS USING clause (when applicable); null for endpoint-only checks';

-- ----------------------------------------------------------------------------
-- AppNavigation: Primary navigation tree for the admin portal. Drives the left sidebar. Each node has a role gate and a target screen. This is the developer's narrative through a rulebook project.
