ALTER TABLE app_navigation ADD COLUMN IF NOT EXISTS icon TEXT;                                      -- Lucide icon name
ALTER TABLE app_navigation ADD COLUMN IF NOT EXISTS screen_id TEXT;                                 -- FK to AppScreens.ScreenId; null for grouping-only nodes
ALTER TABLE app_navigation ADD COLUMN IF NOT EXISTS min_role_id TEXT;                               -- FK to UserRoles.RoleId — minimum role required to see this node
ALTER TABLE app_navigation ADD COLUMN IF NOT EXISTS "order" NUMERIC;
ALTER TABLE app_navigation ADD COLUMN IF NOT EXISTS story_beat TEXT;                                -- What this node teaches the developer in the rulebook narrative
ALTER TABLE app_navigation ADD COLUMN IF NOT EXISTS nav_area TEXT;                                  -- Persona/area bucket: main (everyone), admin (CRUD ops), developer (build/test/tech), docs (educational/training). Drives sidebar section grouping and route prefix.
COMMENT ON TABLE app_navigation IS 'Primary navigation tree for the admin portal. Drives the left sidebar. Each node has a role gate and a target screen. This is the developer''s narrative through a rulebook project.';
COMMENT ON COLUMN app_navigation.parent_nav_id IS 'FK to AppNavigation.NavId; null for top-level nodes';
COMMENT ON COLUMN app_navigation.icon IS 'Lucide icon name';
COMMENT ON COLUMN app_navigation.screen_id IS 'FK to AppScreens.ScreenId; null for grouping-only nodes';
COMMENT ON COLUMN app_navigation.min_role_id IS 'FK to UserRoles.RoleId — minimum role required to see this node';
COMMENT ON COLUMN app_navigation.story_beat IS 'What this node teaches the developer in the rulebook narrative';
COMMENT ON COLUMN app_navigation.nav_area IS 'Persona/area bucket: main (everyone), admin (CRUD ops), developer (build/test/tech), docs (educational/training). Drives sidebar section grouping and route prefix.';

